package alternate;import java.time.*;import java.util.*;public class Schedule implements ScheduleAPI{public record Subject(String id,String name){}public record Teacher(String id,String name){}public enum Kind{THEORY,PRACTICE}public record Lesson(String id,LocalDate date,LocalTime time,String subject,String teacher,String group,String room,Kind kind,String car){Lesson withRoom(String r){return new Lesson(id,date,time,subject,teacher,group,r,kind,car);}}private final Map<String,Subject>subjects=new LinkedHashMap<>();private final Map<String,Teacher>teachers=new LinkedHashMap<>();private final Map<String,String>groups=new LinkedHashMap<>();private final Map<String,Lesson>lessons=new LinkedHashMap<>();private final Set<LocalDate>holidays=new HashSet<>();private boolean active;public boolean active(){return active;}public void createSchedule(){active=true;lessons.clear();holidays.clear();}public void deleteSchedule(){active=false;lessons.clear();holidays.clear();}public void createSubject(String id,String name){if(subjects.containsKey(id))throw new IllegalArgumentException("duplicate id");subjects.put(id,new Subject(id,name));}public void changeSubject(String id,String name){if(!subjects.containsKey(id))throw new IllegalArgumentException();subjects.put(id,new Subject(id,name));}public void deleteSubject(String id){if(lessons.values().stream().anyMatch(l->l.subject.equals(id)))throw new IllegalStateException("referenced subject");subjects.remove(id);}public void createTeacher(String id,String name){if(teachers.containsKey(id))throw new IllegalArgumentException("duplicate id");teachers.put(id,new Teacher(id,name));}public void changeTeacher(String id,String name){if(!teachers.containsKey(id))throw new IllegalArgumentException();teachers.put(id,new Teacher(id,name));}public void deleteTeacher(String id){if(lessons.values().stream().anyMatch(l->l.teacher.equals(id)))throw new IllegalStateException("referenced teacher");teachers.remove(id);}public void createGroup(String id,String name){if(groups.containsKey(id))throw new IllegalArgumentException("duplicate id");groups.put(id,name);}public List<Subject>subjects(){return new ArrayList<>(subjects.values());}public List<Teacher>teachers(){return new ArrayList<>(teachers.values());}public void addLesson(Lesson lesson){if(!active||holidays.contains(lesson.date)||!subjects.containsKey(lesson.subject)||!teachers.containsKey(lesson.teacher)||!groups.containsKey(lesson.group)||lessons.containsKey(lesson.id))throw new IllegalArgumentException("unknown/inactive/holiday/duplicate");lessons.put(lesson.id,lesson);}public void addExtraLesson(Lesson lesson){addLesson(lesson);}public void changeRoom(String id,String room){Lesson old=lessons.get(id);if(old==null)throw new IllegalArgumentException();lessons.put(id,old.withRoom(room));}public void cancelLesson(String id){lessons.remove(id);}public void addHoliday(LocalDate date){holidays.add(date);lessons.values().removeIf(l->l.date.equals(date));}public List<Lesson>forTeacher(String id){return lessons.values().stream().filter(l->l.teacher.equals(id)).toList();}public List<Lesson>forGroup(String id){return lessons.values().stream().filter(l->l.group.equals(id)).toList();}public int countTeacher(String id){return forTeacher(id).size();}public int countGroup(String id){return forGroup(id).size();}}
